plugins: [
  // esbuild alias only supports bare module names; use a plugin to intercept
  // specific server source files that require CF-safe shims.
  {
    name: "server-file-shims",
    setup(build) {
      const SERVER = path.resolve(__dirname, "../../server/src");
      const intercepts = [
        {
          real: path.join(SERVER, "middleware/logger.ts"),
          shim: path.join(SHIMS, "server-logger-shim.ts"),
          filter: /logger/,
        },
        {
          real: path.join(SERVER, "version.ts"),
          shim: path.join(SHIMS, "server-version-shim.ts"),
          filter: /version/,
        },
      ];
      for (const { real, shim, filter } of intercepts) {
        const realNoExt = real.replace(/\.ts$/, "");
        build.onResolve({ filter }, (args) => {
          const resolved = path.resolve(args.resolveDir, args.path);
          if (resolved === real || resolved === realNoExt) {
            return { path: shim };
          }
        });
      }
    },
  },
],

